<script setup lang="ts">
import EvidenceUpload from './EvidenceUpload.vue';
import {useSessionStore} from '../stores/session';
import {ref,watch,onMounted} from 'vue';import {useBusinessStore,businessApi} from '../stores/business';import type {NativeContext,NativePlan} from '@shared/business';
const props=defineProps<{readonly?:boolean;inline?:boolean;roomId?:string;issueId?:string}>(),business=useBusinessStore(),open=ref(false),busy=ref(false),error=ref(''),context=ref<NativeContext>(),targetKind=ref('issue'),targetId=ref(''),files=ref<Array<{id:string;fileName:string;sha256:string;uploaderId:string;uploadedAt:string}>>([]),manuals=ref<Array<{id:string;title:string;device:string;version:string;sourceUrl:string;paragraphs:Array<{id:string;text:string}>}>>([]),query=ref(''),title=ref(''),device=ref(''),version=ref(''),sourceUrl=ref(''),paragraphs=ref(''),visibility=ref('staff'),reviewed=ref(false),dueAt=ref(''),deadlineNote=ref(''),plan=ref<NativePlan>();
async function work(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn();}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
async function loadFiles(){files.value=targetId.value?(await businessApi<{attachments:typeof files.value}>('proxy/evidence/attachments?'+new URLSearchParams({targetKind:targetKind.value,targetId:targetId.value}))).attachments:[];}
async function show(){open.value=true;await work(async()=>{context.value=await businessApi('proxy/context');targetKind.value=props.roomId?'room':'issue';targetId.value=props.roomId||props.issueId||context.value!.issues[0]?.id||'';await loadFiles();await search();});}
async function download(id:string){await work(async()=>{const d=await businessApi<{attachment:{fileName:string;mimeType:string};dataBase64:string}>('proxy/evidence/attachments/'+id),bytes=Uint8Array.from(atob(d.dataBase64),x=>x.charCodeAt(0)),u=URL.createObjectURL(new Blob([bytes],{type:d.attachment.mimeType})),a=document.createElement('a');a.href=u;a.download=d.attachment.fileName;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);});}
async function search(){manuals.value=(await businessApi<{manuals:typeof manuals.value}>('proxy/evidence/manuals?'+new URLSearchParams({q:query.value}))).manuals;}
async function importManual(){if(props.readonly)return;await work(async()=>{const ps=paragraphs.value.split(/\n\s*\n/).filter(x=>x.trim()).map((text,i)=>({id:String(i+1),text:text.trim()}));await businessApi('proxy/evidence/manuals',{scopeKey:business.scopeKey,title:title.value,device:device.value,version:version.value,sourceUrl:sourceUrl.value,visibility:visibility.value,paragraphs:ps,reviewed:reviewed.value});paragraphs.value='';await search();});}
async function previewDeadline(){if(props.readonly)return;await work(async()=>{const i=context.value?.issues.find(i=>i.id===targetId.value);if(!i)throw new Error('请选择当前工单');plan.value=(await businessApi<{plan:NativePlan}>('proxy/workflow/preview',{scopeKey:business.scopeKey,kind:'issue.deadline',issueId:i.id,expectedRevision:i.revision,dueAt:dueAt.value+':00+08:00',note:deadlineNote.value})).plan;});}
async function confirmDeadline(){if(props.readonly||!plan.value)return;await work(async()=>{await businessApi('proxy/plans/commit',{scopeKey:business.scopeKey,planId:plan.value!.id,version:plan.value!.version});plan.value=undefined;context.value=await businessApi('proxy/context');});}
onMounted(()=>{if(props.inline){useSessionStore().startDraft();void show();}});
watch(()=>business.scopeKey,()=>{open.value=false;files.value=[];manuals.value=[];context.value=undefined;plan.value=undefined;});watch(()=>props.readonly,()=>plan.value=undefined);
</script>
<template><div v-if="business.connected&&!inline" class="evidence-entry"><button @click="show">业务证据与设备资料</button></div><div v-if="open"  :class="inline?'evidence-inline':'evidence-mask'" @click.self="!inline&&(open=false)"><section class="evidence-panel" :role="inline?undefined:'dialog'" :aria-modal="inline?undefined:true" aria-label="业务证据与设备资料"><header><b>业务证据与设备资料</b><button v-if="!inline" @click="open=false">关闭</button></header><p v-if="error" role="alert">{{error}}</p>
 <h3>附件</h3><label>绑定对象<select v-model="targetKind" @change="targetId='';files=[]"><option value="issue">本人可见工单</option><option v-if="business.profile?.identity!=='student'" value="room">实验室设备</option></select></label><select v-model="targetId" @change="work(loadFiles)"><option value="">选择业务对象</option><template v-if="targetKind==='issue'"><option v-for="i in context?.issues" :key="i.id" :value="i.id">{{i.description}} · {{i.id}}</option></template><template v-else><option v-for="r in context?.rooms" :key="r.id" :value="r.id">{{r.name}}</option></template></select>
 <EvidenceUpload v-if="!readonly&&targetId&&(targetKind==='issue'||business.profile?.identity==='admin')" :target-kind="targetKind" :target-id="targetId" @saved="work(loadFiles)"/><p>照片、铭牌、维修材料只作为人工依据，不能自动宣告修复验收通过。</p><div v-for="a in files" :key="a.id"><button @click="download(a.id)">{{a.fileName}}</button><p>{{a.uploaderId}} · {{a.uploadedAt}} · SHA256 {{a.sha256}}</p></div>
 <form v-if="!readonly&&targetKind==='issue'&&targetId&&business.profile?.identity==='admin'" @submit.prevent="previewDeadline"><h3>明确工单截止策略</h3><label>截止时间（北京时间）<input v-model="dueAt" type="datetime-local" required></label><label>说明<input v-model="deadlineNote" required maxlength="500"></label><button :disabled="busy">预览截止策略</button></form><div v-if="plan"><p>工单 {{plan.payload.issueId}} 的截止时间将设为 {{(plan.payload as Record<string,unknown>).dueAt}}；仅登记截止，不改变维修状态。</p><button :disabled="busy||readonly" @click="confirmDeadline">本人确认截止策略</button><button @click="plan=undefined">取消</button></div>
 <h3>已审核设备资料</h3><form @submit.prevent="work(search)"><input v-model="query" placeholder="资料标题或段落关键词" maxlength="200"><button :disabled="busy">检索</button></form><p v-if="!manuals.length">没有命中已上传审核的设备资料。维修规范未知。</p><details v-for="m in manuals" :key="m.id"><summary>{{m.title}} · {{m.device}} · v{{m.version}}</summary><a :href="m.sourceUrl" target="_blank" rel="noopener">原始来源</a><p v-for="p in m.paragraphs" :key="p.id">{{m.id}}@{{m.version}}#{{p.id}}：{{p.text}}</p></details>
 <form v-if="!readonly&&business.profile?.identity==='admin'" @submit.prevent="importManual"><h3>导入厂家资料</h3><label>资料名称<input v-model="title" required maxlength="160"></label><label>适用设备<input v-model="device" required maxlength="160"></label><label>版本<input v-model="version" required maxlength="80"></label><label>厂家来源链接<input v-model="sourceUrl" type="url" required placeholder="https://"></label><label>可见范围<select v-model="visibility"><option value="staff">工作人员</option><option value="admin">管理员</option><option value="public">所有登录账号</option></select></label><label>原文段落（空行分隔）<textarea v-model="paragraphs" required rows="6"></textarea></label><label><input v-model="reviewed" type="checkbox" required>已核对厂家来源、版本和适用设备</label><button :disabled="busy">导入并保存版本</button></form>
 </section></div></template>
<style scoped>
.evidence-entry{padding:6px 20px;border-bottom:1px solid var(--border)}button,input,textarea,select{font:inherit;color:var(--text);background:var(--surface-2);border:1px solid var(--border-strong);border-radius:6px;padding:7px 9px;max-width:100%;box-sizing:border-box}button{cursor:pointer}.evidence-mask{position:fixed;inset:0;z-index:70;background:#0006;padding:4dvh 16px;display:flex;justify-content:center}.evidence-panel{background:var(--surface);color:var(--text);width:min(850px,100%);max-height:90dvh;overflow:auto;padding:20px;border-radius:14px;overflow-wrap:anywhere}.evidence-inline .evidence-panel{width:100%;max-height:none;overflow:visible;padding:0;border-radius:0}.evidence-panel header{display:flex;justify-content:space-between}.evidence-panel form{display:grid;gap:10px;padding:16px 0;border-bottom:1px solid var(--border)}.evidence-panel label{display:grid;gap:5px;font-size:13px}.evidence-panel [role=alert]{color:var(--danger)}.evidence-panel p{font-size:13px;white-space:pre-wrap}.evidence-panel input[type=checkbox]{width:16px}
</style>
